// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
        c.seedMarket(1000);
    }

    function testFuzz_property(address actor, uint256 elapsed) public {
        vm.assume(actor != address(0));
        elapsed = bound(elapsed, 1, 30 days);

        vm.prank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);
        vm.assume(kilosBefore > 0);

        vm.warp(block.timestamp + elapsed);
        vm.prank(actor);
        c.collectDrugs(address(0));

        uint256 kilosAfter = c.Kilos(actor);
        // General rule: one collect may at most double the caller's kilos.
        assertTrue(kilosAfter <= 2 * kilosBefore);
    }
}
